#!/usr/bin/env python3
"""Compile standalone CI job definitions into one explicit, platform-aware DAG.

Manual/release entry points remain the source of each suite's jobs. Generated automatic
CI keeps their required result names without reusable-workflow check-name prefixes.
"""
from __future__ import annotations

import argparse
import copy
import json
from pathlib import Path
import re

import yaml

ROOT = Path(__file__).resolve().parents[2]
WORKFLOWS = ROOT / '.github/workflows'
SOURCES = {'core': 'core-ci', 'daemon': 'daemon-ci', 'kit': 'kit-ci', 'python': 'python-check'}
HEADER = '# Generated by .github/scripts/generate-shared-ci.py; edit its source workflows, then regenerate.\n'


def read(name):
    # Only jobs/defaults are read; GitHub's YAML 1.2 `on` key is not used here.
    return yaml.safe_load((WORKFLOWS / f'{name}.yml').read_text())


def remap(value, mapping):
    if isinstance(value, dict):
        return {key: remap(item, mapping) for key, item in value.items()}
    if isinstance(value, list):
        return [remap(item, mapping) for item in value]
    if isinstance(value, str):
        return re.sub(r'needs\.([\w-]+)', lambda m: 'needs.' + mapping.get(m[1], m[1]), value)
    return value


def generate():
    jobs = {}
    workflow = {
        'name': 'Shared / CI',
        'on': {'pull_request': {'types': ['opened', 'synchronize', 'reopened', 'labeled', 'unlabeled']},
               'push': {'branches': ['main']}, 'workflow_dispatch': None},
        'permissions': {'contents': 'read'},
        # Superseded PRs stop the entire graph. Main keeps its publication work and distinct runs.
        'concurrency': {'group': 'shared-ci-${{ github.event.pull_request.number || github.run_id }}',
                        'cancel-in-progress': "${{ github.event_name == 'pull_request' }}"},
        'jobs': jobs,
    }
    for suite, source in SOURCES.items():
        document = read(source)
        source_jobs = document['jobs']
        producer = 'sdk' if suite == 'core' else 'core-sdk'
        mapping = {key: f'{suite}-{key}' for key in source_jobs}
        mapping[producer] = 'sdk-index' if suite == 'core' else f'{suite}-sdk-ready'
        for key, original in source_jobs.items():
            if key == producer:
                continue
            job = remap(copy.deepcopy(original), mapping)
            previous = original.get('needs', [])
            previous = [previous] if isinstance(previous, str) else previous
            needs = [mapping[item] for item in previous if item != producer]
            if producer in previous:
                if key == 'result':
                    needs.append(mapping[producer])
                elif key in ('linux', 'live', 'macos', 'windows'):
                    needs.append('sdk-' + ('linux' if key == 'live' else key))
                else:
                    needs.append(mapping[producer])
            # Source tests, shared/package builds, coverage and sanitizers stay distinct;
            # all platform/deeper core checks wait for the short Linux SDK build/test gate.
            if suite == 'core' and key in ('linux', 'coverage', 'macos', 'windows', 'ubuntu-packages'):
                needs.append('sdk-linux')
            if suite in ('daemon', 'kit') and key == 'ubuntu-packages':
                needs.append('sdk-linux')
            if needs:
                job['needs'] = list(dict.fromkeys(needs))
            # A consumer no longer runs its own SDK producer. Its checked-out commit is
            # the exact run selection; the fetch action verifies archive/tree/configuration.
            def replace_commit(value):
                if isinstance(value, dict):
                    return {k: replace_commit(v) for k, v in value.items()
                            if not (k == 'if' and v == '${{ !inputs.measure_cache }}')}
                if isinstance(value, list):
                    return [replace_commit(v) for v in value
                            if not (isinstance(v, dict) and v.get('if') == 'inputs.measure_cache')]
                if isinstance(value, str):
                    return (value.replace('${{ needs.' + mapping[producer] + '.outputs.commit }}', '${{ github.sha }}')
                        .replace('inputs.measure_cache', 'false')
                        .replace('inputs.core_build_type', "'RelWithDebInfo'")
                        .replace('inputs.core_packages', "'source'"))
                return value
            job = replace_commit(job)
            if 'uses' not in job and 'defaults' in document:
                job['defaults'] = job.get('defaults', copy.deepcopy(document['defaults']))
            if key == 'result':
                # Existing result policies operate on suite-local names. Normalize the
                # generated DAG keys before applying those same policies.
                aliases = {mapping[item]: item for item in previous}
                expression = 'with_entries(.key = (' + json.dumps(aliases, sort_keys=True) + '[.key] // .key))'
                for step in job['steps']:
                    if 'run' in step:
                        step['run'] = 'RESULTS=$(jq \'' + expression + '\' <<< "$RESULTS")\n' + step['run']
            jobs[mapping[key]] = job

    selected = " || ".join(f"needs.{suite}-changes.outputs.{suite} == 'true'" for suite in SOURCES)
    platform_selected = " || ".join(f"needs.{suite}-changes.outputs.{suite} == 'true'" for suite in ('core', 'daemon', 'kit'))
    changes = [f'{suite}-changes' for suite in SOURCES]
    for platform in ('linux', 'macos', 'windows'):
        jobs[f'sdk-{platform}'] = {
            'name': 'Linux gate / SDK' if platform == 'linux' else f'{platform} / SDK',
            'needs': changes if platform == 'linux' else [*changes, 'sdk-linux'],
            'if': selected if platform == 'linux' else platform_selected,
            'permissions': {'actions': 'write', 'contents': 'read'},
            'uses': './.github/workflows/core-sdk.yml',
            'with': {'platforms': f'["{platform}"]', 'selection_name': f'core-selection-{platform}-index'},
        }
    # Core publication still uses the aggregate selection. SDK consumers use the per-platform
    # selections so Linux never waits for another platform's SDK or its failure.
    index = copy.deepcopy(read('core-sdk')['jobs']['index'])
    index['needs'] = ['core-changes', 'sdk-linux', 'sdk-macos', 'sdk-windows']
    index['if'] = "needs.core-changes.outputs.core == 'true'"
    index['defaults'] = {'run': {'working-directory': 'core'}}
    index['steps'][1]['with']['pattern'] = 'core-sdk-*-RelWithDebInfo'
    index['steps'][-1]['with']['name'] = 'core-selection'
    jobs['sdk-index'] = index
    jobs['core-sanitizers'] = {
        'needs': ['core-changes', 'sdk-linux'],
        'if': "needs.core-changes.outputs.core == 'true'",
        'uses': './.github/workflows/core-sanitizers.yml',
    }
    for suite in ('daemon', 'kit', 'python'):
        jobs[f'{suite}-sdk-ready'] = {
            'needs': [f'{suite}-changes', 'sdk-linux'] + ([] if suite == 'python' else ['sdk-macos', 'sdk-windows']),
            'if': f"needs.{suite}-changes.outputs.{suite} == 'true'",
            'runs-on': 'ubuntu-24.04',
            'steps': [{'run': 'echo "Required SDK producers passed; platform consumers verify their artifacts."'}],
        }
    # Include the new essential result in the existing Core result policy.
    jobs['core-publish-sdk']['needs'].append('core-sanitizers')
    result = jobs['core-result']
    result['needs'].append('core-sanitizers')
    for step in result['steps']:
        if 'run' in step:
            step['run'] = step['run'].replace('.coverage,', '.["core-sanitizers"], .coverage,')
    # Automatic main publication needs environment secrets, just as the standalone source jobs.
    class Dumper(yaml.SafeDumper):
        pass

    def string(dumper, value):
        return dumper.represent_scalar('tag:yaml.org,2002:str', value, style='|' if '\n' in value else None)

    Dumper.add_representer(str, string)
    return HEADER + yaml.dump(workflow, Dumper=Dumper, sort_keys=False, width=110)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    destination = WORKFLOWS / 'shared-ci.yml'
    generated = generate()
    if args.check:
        if not destination.exists() or destination.read_text() != generated:
            parser.exit(1, 'Regenerate .github/workflows/shared-ci.yml with this script.\n')
    else:
        destination.write_text(generated)


if __name__ == '__main__':
    main()
